def slugify(text):
    out = []
    last_dash = True
    for ch in text.lower():
        if ch.isalnum():
            out.append(ch)
            last_dash = False
        elif not last_dash:
            out.append("-")
            last_dash = True
    return "".join(out).strip("-")

def t_spaces_become_one_dash():
    assert slugify("Hello World") == "hello-world"
def t_punctuation_runs_collapse():
    assert slugify("Hello,   World!!") == "hello-world"
def t_edges_stripped():
    assert slugify("  --Hello--  ") == "hello"
def t_digits_kept():
    assert slugify("Top 10 Tips") == "top-10-tips"
def t_empty_and_symbols_only():
    assert slugify("") == ""
    assert slugify("***") == ""
TESTS = [("spaces become one dash", t_spaces_become_one_dash), ("punctuation runs collapse", t_punctuation_runs_collapse), ("edges stripped", t_edges_stripped), ("digits kept", t_digits_kept), ("empty and symbols only", t_empty_and_symbols_only)]

