def clamp(value, low, high):
    if value < low:
        return low
    if value > high:
        return high
    return value

def t_below():
    assert clamp(-5, 0, 10) == 0
def t_above():
    assert clamp(99, 0, 10) == 10
def t_inside():
    assert clamp(7, 0, 10) == 7
def t_at_low():
    assert clamp(0, 0, 10) == 0
def t_at_high():
    assert clamp(10, 0, 10) == 10
def t_negative_range():
    assert clamp(-50, -20, -1) == -20
    assert clamp(0, -20, -1) == -1
def t_floats():
    assert clamp(0.25, 0.5, 1.5) == 0.5
