def fizzbuzz(n):
    out = []
    for i in range(1, n + 1):
        if i % 15 == 0:
            out.append("FizzBuzz")
        elif i % 3 == 0:
            out.append("Fizz")
        elif i % 5 == 0:
            out.append("Buzz")
        else:
            out.append(str(i))
    return out

def t_first_fifteen_exact():
    assert fizzbuzz(15) == ["1","2","Fizz","4","Buzz","Fizz","7","8","Fizz","Buzz","11","Fizz","13","14","FizzBuzz"]
def t_length():
    assert len(fizzbuzz(100)) == 100
def t_zero_is_empty():
    assert fizzbuzz(0) == []
def t_counts():
    seq = fizzbuzz(30)
    assert seq.count("FizzBuzz") == 2
    assert seq.count("Fizz") == 8
    assert seq.count("Buzz") == 4
TESTS = [("first fifteen exact", t_first_fifteen_exact), ("length matches n", t_length), ("zero gives empty", t_zero_is_empty), ("category counts to 30", t_counts)]

