def is_palindrome(text):
    chars = [c.lower() for c in text if c.isalnum()]
    return chars == chars[::-1]

def t_phrase():
    assert is_palindrome("A man, a plan, a canal: Panama") is True
def t_simple():
    assert is_palindrome("Racecar") is True
def t_near_miss():
    assert is_palindrome("A man, a plan, a canal: Panamax") is False
def t_plain_false():
    assert is_palindrome("hello") is False
def t_empty_is_true():
    assert is_palindrome("") is True
    assert is_palindrome("?!...") is True
def t_digits():
    assert is_palindrome("12,321") is True
    assert is_palindrome("12,312") is False
TESTS = [("phrase palindrome", t_phrase), ("simple word", t_simple), ("near miss", t_near_miss), ("plain false", t_plain_false), ("empty after cleaning", t_empty_is_true), ("digits count", t_digits)]

