import re
def word_count(text):
    counts = {}
    for w in re.findall(r"[A-Za-z0-9]+(?:'[A-Za-z0-9]+)?", text.lower()):
        counts[w] = counts.get(w, 0) + 1
    return counts

def t_basic():
    assert word_count("the cat and the dog") == {"the": 2, "cat": 1, "and": 1, "dog": 1}
def t_case_folds():
    assert word_count("Dog DOG dog") == {"dog": 3}
def t_apostrophe_kept():
    assert word_count("don't can't don't") == {"don't": 2, "can't": 1}
def t_punctuation_separates():
    assert word_count("hello,world! hello") == {"hello": 2, "world": 1}
def t_empty():
    assert word_count("") == {}
    assert word_count("  --  ") == {}
def t_numbers_are_words():
    assert word_count("abc 123 abc 123 123") == {"abc": 2, "123": 3}
TESTS = [("basic frequencies", t_basic), ("case folds", t_case_folds), ("apostrophe kept", t_apostrophe_kept), ("punctuation separates", t_punctuation_separates), ("empty input", t_empty), ("numbers are words", t_numbers_are_words)]

