def parse_amount(text):
    cleaned = text.strip().replace(",", "")
    if not cleaned or not cleaned.lstrip("-").isdigit():
        raise ValueError("not an amount: " + repr(text))
    return int(cleaned)

def t_plain():
    assert parse_amount("42") == 42
def t_commas():
    assert parse_amount("1,234,567") == 1234567
def t_whitespace():
    assert parse_amount("  99 ") == 99
def t_negative():
    assert parse_amount("-250") == -250
def t_rejects_decimal():
    try:
        parse_amount("12.5")
        raise AssertionError("should have raised")
    except ValueError:
        pass
def t_rejects_junk():
    for bad in ["", "abc", "1,2a3", "--5", "1 000"]:
        try:
            parse_amount(bad)
            raise AssertionError("accepted " + repr(bad))
        except ValueError:
            pass
TESTS = [("plain integer", t_plain), ("thousands commas", t_commas), ("surrounding whitespace", t_whitespace), ("negative", t_negative), ("decimal rejected", t_rejects_decimal), ("junk rejected", t_rejects_junk)]

