def dedupe(items):
    seen = set()
    out = []
    for x in items:
        if x not in seen:
            seen.add(x)
            out.append(x)
    return out

def t_basic():
    assert dedupe([3, 1, 3, 2, 1]) == [3, 1, 2]
def t_no_dupes_unchanged():
    assert dedupe([1, 2, 3]) == [1, 2, 3]
def t_all_same():
    assert dedupe([7, 7, 7]) == [7]
def t_empty():
    assert dedupe([]) == []
def t_strings():
    assert dedupe(["b", "a", "b", "c", "a"]) == ["b", "a", "c"]
def t_first_occurrence_wins():
    assert dedupe([2, 9, 2, 9, 5]) == [2, 9, 5]
TESTS = [("basic dedupe", t_basic), ("no duplicates unchanged", t_no_dupes_unchanged), ("all same", t_all_same), ("empty", t_empty), ("strings", t_strings), ("first occurrence wins", t_first_occurrence_wins)]

