def merge_counts(a, b):
    out = dict(a)
    for k, v in b.items():
        out[k] = out.get(k, 0) + v
    return out

def t_shared_keys_sum():
    assert merge_counts({"a": 1, "b": 2}, {"b": 3, "c": 4}) == {"a": 1, "b": 5, "c": 4}
def t_disjoint():
    assert merge_counts({"a": 1}, {"z": 9}) == {"a": 1, "z": 9}
def t_empty_side():
    assert merge_counts({}, {"a": 1}) == {"a": 1}
    assert merge_counts({"a": 1}, {}) == {"a": 1}
def t_both_empty():
    assert merge_counts({}, {}) == {}
def t_inputs_not_mutated():
    a = {"a": 1}
    b = {"a": 2, "b": 1}
    merge_counts(a, b)
    assert a == {"a": 1}
    assert b == {"a": 2, "b": 1}
def t_zero_and_negative():
    assert merge_counts({"a": 5}, {"a": -5}) == {"a": 0}
TESTS = [("shared keys sum", t_shared_keys_sum), ("disjoint keys", t_disjoint), ("empty side", t_empty_side), ("both empty", t_both_empty), ("inputs not mutated", t_inputs_not_mutated), ("zero and negative sums kept", t_zero_and_negative)]

