from collections import Counter
def mode_value(values):
    if not values:
        return None
    counts = Counter(values)
    top = max(counts.values())
    return min(v for v, c in counts.items() if c == top)

def t_clear_winner():
    assert mode_value([1, 2, 2, 3]) == 2
def t_tie_picks_smallest():
    assert mode_value([5, 5, 3, 3]) == 3
def t_single():
    assert mode_value([42]) == 42
def t_empty():
    assert mode_value([]) is None
def t_all_unique_picks_min():
    assert mode_value([9, 4, 7]) == 4
def t_strings():
    assert mode_value(["b", "a", "b", "a", "b"]) == "b"
TESTS = [("clear winner", t_clear_winner), ("tie picks smallest", t_tie_picks_smallest), ("single value", t_single), ("empty gives None", t_empty), ("all unique picks min", t_all_unique_picks_min), ("strings", t_strings)]

