def interleave(a, b):
    out = []
    for i in range(max(len(a), len(b))):
        if i < len(a):
            out.append(a[i])
        if i < len(b):
            out.append(b[i])
    return out

def t_equal_lengths():
    assert interleave([1, 3, 5], [2, 4, 6]) == [1, 2, 3, 4, 5, 6]
def t_first_longer():
    assert interleave([1, 3, 5, 7], [2, 4]) == [1, 2, 3, 4, 5, 7]
def t_second_longer():
    assert interleave([1], [2, 4, 6]) == [1, 2, 4, 6]
def t_both_empty():
    assert interleave([], []) == []
def t_one_empty():
    assert interleave([], ["x", "y"]) == ["x", "y"]
    assert interleave(["x"], []) == ["x"]
TESTS = [("equal lengths", t_equal_lengths), ("first longer", t_first_longer), ("second longer", t_second_longer), ("both empty", t_both_empty), ("one empty", t_one_empty)]

