def transpose(matrix):
    if not matrix:
        return []
    return [list(col) for col in zip(*matrix)]

def t_square():
    assert transpose([[1, 2], [3, 4]]) == [[1, 3], [2, 4]]
def t_wide():
    assert transpose([[1, 2, 3], [4, 5, 6]]) == [[1, 4], [2, 5], [3, 6]]
def t_tall():
    assert transpose([[1, 4], [2, 5], [3, 6]]) == [[1, 2, 3], [4, 5, 6]]
def t_single_row():
    assert transpose([[1, 2, 3]]) == [[1], [2], [3]]
def t_empty():
    assert transpose([]) == []
def t_roundtrip():
    m = [[1, 2, 3], [4, 5, 6]]
    assert transpose(transpose(m)) == m
TESTS = [("square", t_square), ("wide matrix", t_wide), ("tall matrix", t_tall), ("single row", t_single_row), ("empty", t_empty), ("double transpose round-trips", t_roundtrip)]

