def caesar(text, shift):
    out = []
    s = shift % 26
    for ch in text:
        if "a" <= ch <= "z":
            out.append(chr((ord(ch) - 97 + s) % 26 + 97))
        elif "A" <= ch <= "Z":
            out.append(chr((ord(ch) - 65 + s) % 26 + 65))
        else:
            out.append(ch)
    return "".join(out)

def t_basic():
    assert caesar("abc", 1) == "bcd"
def t_wrap():
    assert caesar("xyz", 3) == "abc"
def t_case_preserved():
    assert caesar("AbC", 2) == "CdE"
def t_non_letters():
    assert caesar("a b!2", 1) == "b c!2"
def t_shift_26_identity():
    assert caesar("Hello", 26) == "Hello"
def t_big_shift():
    assert caesar("abc", 29) == "def"
def t_negative():
    assert caesar("bcd", -1) == "abc"
def t_rot13_roundtrip():
    msg = "Secret Message"
    assert caesar(caesar(msg, 13), 13) == msg
