DAYS = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
def is_leap(y):
    return y % 4 == 0 and (y % 100 != 0 or y % 400 == 0)
def day_of_year(year, month, day):
    total = sum(DAYS[:month - 1]) + day
    if month > 2 and is_leap(year):
        total += 1
    return total

