from decimal import Decimal, ROUND_HALF_UP
def percent(part, whole):
    if whole == 0:
        return 0.0
    value = (Decimal(part) * Decimal(100) / Decimal(whole)).quantize(Decimal("0.1"), rounding=ROUND_HALF_UP)
    return float(value)

def t_simple():
    assert percent(1, 4) == 25.0
    assert percent(1, 3) == 33.3
def t_half_up_tie():
    assert percent(1, 16) == 6.3
def t_half_up_tie_two():
    assert percent(3, 8) == 37.5
def t_zero_whole():
    assert percent(5, 0) == 0.0
def t_zero_part():
    assert percent(0, 10) == 0.0
