    rb = RingBuffer(3)
    for x in [1, 2, 3]:
        rb.push(x)
    assert rb.items() == [1, 2, 3]
def t_one_past_capacity():
    rb = RingBuffer(3)
    for x in [1, 2, 3, 4]:
        rb.push(x)
    assert rb.items() == [2, 3, 4]
def t_many_past():
    rb = RingBuffer(3)
    for x in range(10):
