import random
def encode(text):
    if not text:
        return ""
    out = []
    run = 1
    for i in range(1, len(text)):
        if text[i] == text[i - 1]:
            run += 1
        else:
            out.append(str(run) + text[i - 1])
            run = 1
    out.append(str(run) + text[-1])
    return "".join(out)

def decode(code):
    out = []
    i = 0
    while i < len(code):
        j = i
        while code[j].isdigit():
            j += 1
        out.append(code[j] * int(code[i:j]))
        i = j + 1
    return "".join(out)

def t_known():
    assert encode("aaabcc") == "3a1b2c"
    assert decode("3a1b2c") == "aaabcc"
    assert encode("") == ""
    assert decode("") == ""
def t_roundtrip_seeded():
    rng = random.Random(42)
    for _ in range(80):
        text = "".join(rng.choice("aab") for _ in range(rng.randint(0, 30)))
        assert decode(encode(text)) == text
def t_long_run_two_digits():
    assert decode(encode("a" * 15)) == "a" * 15
    assert encode("a" * 15) == "15a"
TESTS = [("known encodings", t_known), ("round trip over seeded strings", t_roundtrip_seeded), ("run longer than nine", t_long_run_two_digits)]

