import random
from collections import deque
class Queue:
    def __init__(self):
        self._data = deque()
    def enqueue(self, x):
        self._data.append(x)
    def dequeue(self):
        return self._data.popleft()
    def front(self):
        return self._data[0]
    def size(self):
        return len(self._data)

def t_model_sweep():
    rng = random.Random(1234)
    for _ in range(25):
        q = Queue()
        model = deque()
        for _ in range(50):
            if model and rng.random() < 0.5:
                assert q.dequeue() == model.popleft()
            else:
                v = rng.randint(0, 50)
                q.enqueue(v)
                model.append(v)
            assert q.size() == len(model)
            if model:
                assert q.front() == model[0]
def t_fifo_order():
    q = Queue()
    for x in ["a", "b", "c"]:
        q.enqueue(x)
    assert [q.dequeue(), q.dequeue(), q.dequeue()] == ["a", "b", "c"]
TESTS = [("deque model sweep", t_model_sweep), ("plain fifo order", t_fifo_order)]

