import random
def dedupe(items):
    seen = set()
    out = []
    for x in items:
        if x not in seen:
            seen.add(x)
            out.append(x)
    return out

def is_subsequence(sub, full):
    it = iter(full)
    return all(any(x == y for y in it) for x in sub)

def t_seeded_properties():
    rng = random.Random(77)
    for _ in range(60):
        data = [rng.randint(0, 5) for _ in range(rng.randint(0, 20))]
        out = dedupe(data)
        assert len(out) == len(set(out))
        assert set(out) == set(data)
        assert is_subsequence(out, data)
        assert dedupe(out) == out
