import random
def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def t_seeded_laws():
    rng = random.Random(15)
    for _ in range(80):
        a = rng.randint(0, 500)
        b = rng.randint(0, 500)
        if a == 0 and b == 0:
            continue
        g = gcd(a, b)
        assert g >= 1
        assert a % g == 0 and b % g == 0
        assert gcd(b, a) == g
        for d in range(1, 30):
            if a % d == 0 and b % d == 0:
                assert g % d == 0
def t_zero_identity():
    assert gcd(12, 0) == 12
    assert gcd(0, 7) == 7
