import random
def merge_left(a, b):
    out = dict(b)
    out.update(a)
    return out

def t_seeded_properties():
    rng = random.Random(2024)
    keys = ["a", "b", "c", "d", "e"]
    for _ in range(50):
        a = {k: rng.randint(0, 9) for k in rng.sample(keys, rng.randint(0, 5))}
        b = {k: rng.randint(0, 9) for k in rng.sample(keys, rng.randint(0, 5))}
        out = merge_left(a, b)
        assert set(out.keys()) == set(a.keys()) | set(b.keys())
        for k, v in a.items():
            assert out[k] == v
        for k, v in b.items():
            if k not in a:
                assert out[k] == v
        assert merge_left(a, {}) == a
        assert merge_left({}, b) == b
