import random
def binary_search(sorted_items, target):
    lo, hi = 0, len(sorted_items) - 1
    while lo <= hi:
        mid = (lo + hi) // 2
        if sorted_items[mid] == target:
            return mid
        if sorted_items[mid] < target:
            lo = mid + 1
        else:
            hi = mid - 1
    return -1

def t_seeded_agreement():
    rng = random.Random(555)
    for _ in range(50):
        data = sorted(rng.randint(0, 40) for _ in range(rng.randint(0, 20)))
        for target in [rng.randint(0, 40) for _ in range(6)]:
            idx = binary_search(data, target)
            if target in data:
                assert idx >= 0 and data[idx] == target
            else:
                assert idx == -1
def t_edges():
    assert binary_search([], 5) == -1
    assert binary_search([5], 5) == 0
    assert binary_search([5], 4) == -1
    assert binary_search([1, 2, 3], 1) == 0
    assert binary_search([1, 2, 3], 3) == 2
