def parse_price(text):
    cleaned = text.strip().lstrip("$").replace(",", "")
    if "." in cleaned:
        dollars, cents = cleaned.split(".")
        cents = (cents + "00")[:2]
    else:
        dollars, cents = cleaned, "00"
    return int(dollars) * 100 + int(cents)

