class Stack:
    def __init__(self):
        self._data = []
    def push(self, x):
        self._data.append(x)
    def pop(self):
        if not self._data:
            raise IndexError("stack is empty")
        return self._data.pop()
    def peek(self):
        if not self._data:
            raise IndexError("stack is empty")
        return self._data[-1]

