import asyncio
async def pipeline(items):
    queue = asyncio.Queue()
    consumed = []
    async def producer():
        for item in items:
            await queue.put(item)
        await queue.put(None)
    async def consumer():
        while True:
            item = await queue.get()
            if item is None:
