import asyncio
async def scenario(cancel):
    state = {"cleaned": False, "finished": False}
    started = asyncio.Event()
    async def worker():
        try:
            started.set()
            await asyncio.Event().wait()
            state["finished"] = True
        finally:
            state["cleaned"] = True
    task = asyncio.create_task(worker())
    await started.wait()
    if cancel:
        task.cancel()
        try:
            await task
        except asyncio.CancelledError:
            pass
    else:
        task.cancel()
        try:
            await task
        except asyncio.CancelledError:
            pass
    return state

def t_cancel_runs_finally():
    state = asyncio.run(scenario(True))
    assert state["cleaned"] is True
    assert state["finished"] is False
def t_worker_was_blocked_not_finished():
    state = asyncio.run(scenario(True))
    assert state["finished"] is False
