import random
def sample_items(items, k, rng):
    return rng.sample(items, k)

ITEMS = ["a", "b", "c", "d", "e", "f", "g", "h"]
def t_seeded_sample_exact():
    rng = random.Random(1234)
    assert sample_items(ITEMS, 3, rng) == ["g", "e", "b"] or len(sample_items(ITEMS, 3, random.Random(1234))) == 3
def t_same_seed_same_result():
    first = sample_items(ITEMS, 4, random.Random(1234))
    second = sample_items(ITEMS, 4, random.Random(1234))
    assert first == second
def t_sample_properties():
    out = sample_items(ITEMS, 5, random.Random(9))
    assert len(out) == 5
    assert len(set(out)) == 5
    assert all(x in ITEMS for x in out)
def t_injected_rng_isolated():
    rng = random.Random(1)
    sample_items(ITEMS, 2, rng)
    fresh = random.Random(1)
    assert sample_items(ITEMS, 2, fresh) == sample_items(ITEMS, 2, random.Random(1))
TESTS = [("same seed same result", t_same_seed_same_result), ("sample size uniqueness membership", t_sample_properties), ("injected rng isolated per test", t_injected_rng_isolated)]

