def discounted_total(subtotal_cents, discount_percent):
    effective = min(discount_percent, 100)
    return subtotal_cents * (100 - effective) // 100

def t_normal_discount():
    assert discounted_total(10000, 10) == 9000
def t_exactly_100_free():
    assert discounted_total(10000, 100) == 0
def t_over_100_clamped():
    assert discounted_total(10000, 110) == 0
def t_way_over_clamped():
    assert discounted_total(5999, 250) == 0
def t_zero_discount():
    assert discounted_total(5999, 0) == 5999
def t_never_negative_sweep():
    for pct in [0, 25, 50, 99, 100, 101, 200]:
        assert discounted_total(12345, pct) >= 0
TESTS = [("normal discount", t_normal_discount), ("exactly 100 makes it free", t_exactly_100_free), ("110 percent clamped to free", t_over_100_clamped), ("250 percent clamped", t_way_over_clamped), ("zero discount", t_zero_discount), ("never negative sweep", t_never_negative_sweep)]

