class TemperatureLog:
    def __init__(self):
        self._readings = []
    def record(self, celsius):
        self._readings.append(celsius)
    def count(self):
        return len(self._readings)
    def average(self):
        if not self._readings:
            return None
        return sum(self._readings) / len(self._readings)

def t_count_public():
    log = TemperatureLog()
    assert log.count() == 0
    log.record(20.0)
    log.record(22.0)
    assert log.count() == 2
def t_average_public():
    log = TemperatureLog()
    log.record(20.0)
    log.record(22.0)
    assert log.average() == 21.0
def t_average_empty_none():
    assert TemperatureLog().average() is None
def t_average_float_tolerance():
    log = TemperatureLog()
    for v in [0.1, 0.2, 0.3]:
        log.record(v)
    assert abs(log.average() - 0.2) < 1e-9
TESTS = [("count through public api", t_count_public), ("average through public api", t_average_public), ("empty average is None", t_average_empty_none), ("average with float tolerance", t_average_float_tolerance)]

